#include <bits/stdc++.h>
using namespace std;

using ll = long long;

vector<ll> v;

void generatePowers(ll n) {
    for (ll i = 1; i <= n;) {
        v.push_back(i);
        if (i > n / 2) break;
        i *= 2;
    }
}

int main() {
    ll n, k;
    cin >> n >> k;

    generatePowers(n);

    ll ans = 0;
    ll used = 0;

    for (ll i = static_cast<ll>(v.size()) - 1; i >= 0 && used < k; --i, ++used) {
        ans += v[i];
    }

    cout << ans << '\n';
    return 0;
}

